#include "config.h"
#include <iostream>
#include <string>

int main() {
    DeferredConfig config;
    std::string source = "title=forest";
    config.queue(source);
    source[6] = 'x';
    if (config.pending() != "title=forest") {
        std::cerr << "queued text changed with the caller buffer\n";
        return 1;
    }
}

